import{_ as b,d as a,e as c,f as t,X as d,i as r,k as v,x as s,g as e,h as i,a8 as l,y as n,r as o,Q as P,F as p,G as m}from"./app-54456723.js";/* empty css                                                                 */import{W as h}from"./Watermark-10cbdb89.js";import{u}from"./vue.-sixQ7xP-dd91a7dd.js";const A={class:"container"},_={class:"content"},g=["src"],y={class:"image-scroll-container"},k=["src"],f=b({__name:"privacy",setup(b){const P=n("/imgs/privacy_1.png"),p=n("/imgs/privacy_2.png"),m=o(!1);return(b,n)=>(a(),c("div",A,[t("div",_,[n[4]||(n[4]=d(" 【定义】本政策中，【我们】统一解释定义为东风乘用车科技(成都)有限公司及其关联公司，以下统称“奕境汽车”或“我们”。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 欢迎您使用我们的产品和服务！我们深知个人信息的重要性，也致力于保护每个用户的个人信息。您的信赖对我们至关重要，我们将严格遵守相关法律法规要求采取相应的安全保护措施，使您的个人信息安全可控。基于此，我们制定了《奕境汽车隐私政策》（以下简称“本政策”或“隐私协议”），帮助您充分了解您在使用我们的产品和服务的过程中，我们会如何收集、使用、共享、存储和保护您的个人信息以及您可以如何管理您的个人信息，以便您更好地作出适当的选择。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 本隐私政策适用于您通过奕境汽车官方网站、奕境汽车APP、奕境汽车小程序（以下合称“三端平台”）及相关服务所获取的所有产品与服务。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 在您开始使用我们的产品和服务前，请您务必先仔细阅读和理解本政策，确保您充分理解和同意之后再开始使用。您点击同意即视为您已阅读并同意本协议的全部内容。为给您提供更好的服务，本政策可能适时修订。未经您明确同意，我们不会削减您按照本政策所应享有的权利。对于重大变更，我们将在生效前通过APP内弹窗、推送通知等显著方式提示您，并再次取得您的同意。当本协议的任何一条被视为废止、宣告无效或因任何理由不可执行，该条应视为可分的且不影响其他条款的有效性和可执行性。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>隐私保护原则</h4> 我们严格遵循《中华人民共和国个人信息保护法》等法律法规，遵循以下隐私保护原则，为您提供安全、可靠的服务： <br data-v-19bb5c0c><br data-v-19bb5c0c> 1.安全可靠：我们通过合理有效的信息安全技术及管理制度，保证您的信息安全无虞，防止您的信息泄露或者被篡改。我们在产品或者服务开发的各个环节，综合法律、产品、设计等多个要素，全面融入隐私保护的理念。 <br data-v-19bb5c0c> 2.自主自愿：我们为您提供便利的信息管理选项，以便您做出自己的选择，保护您的个人信息。 <br data-v-19bb5c0c> 3.合理必要：我们严格遵照《中华人民共和国网络安全法》及相关法律法规的规定，仅向您收集必要的有限信息，与我们的服务无关的信息我们禁止收集。 <br data-v-19bb5c0c> 4.清晰透明：我们努力使用简明易懂的表述，向您介绍我们的隐私政策，以便您轻松掌握我们的信息处理全过程。您可以随时查询我们收集使用信息的情况，也可以要求我们更正或者删除已收集的信息，甚至可以注销账户。您还可以对我们关于信息安全方面的服务进行投诉或者举报，欢迎随时联系我们。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>本政策将帮助您了解以下内容：</h4><br data-v-19bb5c0c> 一、我们收集和使用的信息 <br data-v-19bb5c0c> 二、信息的第三方合作、共享、转移和公开 <br data-v-19bb5c0c> 三、信息的存储和保护 <br data-v-19bb5c0c> 四、存储期限和超期使用说明 <br data-v-19bb5c0c> 五、您的权利 <br data-v-19bb5c0c> 六、未成年人保护 <br data-v-19bb5c0c> 七、政策更新 <br data-v-19bb5c0c> 八、联系我们 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>一、我们收集和使用的信息</h4> 为实现向您提供我们的产品和/或服务的扩展业务功能，您可选择授权我们收集、使用您的信息。如您拒绝提供，您将无法正常使用相关扩展业务功能或无法达到我们拟达到的功能效果，但并不会影响您正常使用我们的产品和/或服务的基本业务功能。我们会根据您在软件安装及/或使用中的具体操作，接收并记录您所使用的设备相关信息（包括设备型号、操作系统版本、设备设置、网络信息、加速度传感器信息等），用于保障服务运行与网络安全、进行用户设备适配及问题排查。我们承诺仅在实现上述目的所必需的范围内收集和使用上述设备信息。如果您不同意隐私政策，您可选择进入仅浏览模式，进行部分社区内容的查看，此功能下不收集您的个人信息。在您使用我们的产品和/或服务时，我们需要/可能需要收集和使用您的个人信息包括如下场景： <br data-v-19bb5c0c><br data-v-19bb5c0c>",48)),t("img",{style:{width:"100%",cursor:"zoom-in"},src:r(P),onClick:n[0]||(n[0]=b=>m.value=!0),alt:"隐私政策表格"},null,8,g),n[5]||(n[5]=d("<br data-v-19bb5c0c><br data-v-19bb5c0c> 1.用户注册及登录 <br data-v-19bb5c0c> 当您注册或登录奕境三端平台账号时，您需要向我们提供您的手机号码作为识别您身份的信息，我们将通过发送短信验证码来验证您的身份是否有效。 <br data-v-19bb5c0c> 如果您不想进行注册登录，您可选择进入仅浏览模式进行部分社区内容的查看，仅浏览模式下您无需提供上述信息。若您手机号码更换或注销后，请您及时登录奕境汽车APP/小程序通过“我的-设置-个人中心-账号安全”进行手机号码换绑。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 2.个人资料 <br data-v-19bb5c0c> 为了展示您的资料，您可以在奕境汽车APP/小程序端填写/修改/补充您的个人资料，个人资料包括您的头像、昵称、性别、生日、地区和简介，具体以页面展示为准。您可以自主决定是否填写上述信息，如果您不填写上述信息，不影响您正常使用我们的产品和/或服务。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 3.第三方登录及一键登录 <br data-v-19bb5c0c> 当您使用“第三方登录”功能时，您可以使用第三方平台的账号登录并使用我们的产品和/或服务，您将授权我们获取您在第三方平台的账号信息（包括：头像、昵称，具体以您的实际授权为准），与您的账号进行绑定，用于快捷登录，使您可以直接登录并使用我们的产品和/或服务。我们会依据与第三方的约定，在符合相关法规的前提下，使用您的个人信息。具体授权信息以登录界面提示为准。 <br data-v-19bb5c0c> 当您使用“一键登录”功能时，基于您的同意，第三方服务运营商会将您的手机号码共享给我们，以便您可以使用一键登录服务。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 4.预约品鉴/试乘试驾 <br data-v-19bb5c0c> 我们的产品和/或服务包含预约品鉴/试乘试驾的功能，您可以通过奕境三端平台预约品鉴/试乘试驾，当您需要预约品鉴/试乘试驾时，您需要填写或提供姓名、手机号码、地点、车型（具体以页面展示您的授权信息为准）。若您已开启位置权限，基于您的单独同意，我们将申请您授权我们使用您的位置信息，为您推荐最近的地点。我们将基于您主动提供的上述信息安排我们的工作人员与您联系，为您提供服务。您也可以选择手动输入您的位置或直接前往线下门店进行品鉴/试乘试驾。 <br data-v-19bb5c0c> 当您在门店进行试乘试驾前，您需要提供试乘试驾人的姓名、手机号码、身份证信息用于签署试乘试驾协议；为了核验试驾人身份信息及驾驶资质，我们会要求您提供试驾人的机动车驾驶证、试乘人的身份证并进行信息核验。当您为他人预约试乘试驾时，请确保已取得个人信息主体的同意。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 5.预定购车 <br data-v-19bb5c0c> 当您预订车辆时，我们或我们授权的合作商会收集购车人姓名、手机号码、性别、用车城市、销售门店、销售姓名及手机号码，并记录您选择的车型及配置信息、价款及支付信息、交付及相关权益信息；当您签订购车合同时，我们会补充收集上牌人姓名、有效身份证件号码（身份证件或护照、军官证、港澳居民居住证、台湾居民居住证等有效证件号码）、联系电话、联系地址，以便于我们跟进处理您的购车订单。同时，我们依据前述信息给您开具相应发票。 <br data-v-19bb5c0c> 您下单后可以选择第三方支付机构（例如微信、支付宝、银联）所提供的支付服务，支付功能本身并不收集您的个人信息，但我们需要将您的订单号与交易金额信息与这些支付机构共享，以实现其确认您的支付指令并完成支付。 <br data-v-19bb5c0c> 为完成您订购车辆的交付，我们会将您的订单信息提供给我们合作的物流配送服务商，以便其为您提供配送服务。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 6.金融计算器 <br data-v-19bb5c0c> 为您提供金融贷款中金融产品的查询及计算功能，仅做贷款方案计算功能，不会将任何您的个人信息（包括、手机号、用户昵称、购买车型、贷款计算结果及纪律等）传递给第三方。 <br data-v-19bb5c0c> 在本平台进行金融方案查询及试算功能仅作参考，该数据结果与实际贷款使用的汽车金融服务无关，请以实际通过金融机构进件并出具的最终分期方案为准。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 7.客户服务与售后功能 <br data-v-19bb5c0c> 当您与我们的客户服务人员沟通时，为保证您的账号安全，我们会使用您的账号信息核验您的身份。同时我们可能为您提供专属的服务专家和基于您服务需求的维修专家与您进行沟通。当您需要我们提供与您订单信息相关的客户服务与售后功能时，我们将会查询您的订单信息。当您在与我们的客户服务人员沟通时，基于您不同的客服需求，可能还需要您提供上述信息外的其他信息，以便我们为您解决问题，具体以实际沟通场景为准。我们会保留您与客户服务人员的沟通记录，会以通话录音及人工录入的方式记录您的通话信息，以便于我们解决问题、向您反馈结果或处理纠纷。 <br data-v-19bb5c0c> 车辆交付后，为了履行法定义务、保证车辆持续运行、进行安全分析、甄别和解决潜在问题、事故追查，我们需要通过汽车产品的配套车载感应设备收集和处理与车辆使用、操作和状况有关的车辆数据，包含车辆VIN码、车辆行驶状态数据（如档位、电机转速、电池电量）、车身基础数据（如电子稳定系统工作状态、悬架工作状态）、电器设备工作状态数据（如空调工作状态、车门车窗车锁开启状态、座椅调节开关工作状态）、辅助驾驶工作状态数据。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 8.用户社区 <br data-v-19bb5c0c> 为了方便您共享用户体验，我们为您提供用户社区交流、内容分享服务。在您使用该等服务时我们将记录您的昵称、关注、点赞、评论、粉丝情况以及记录您发布、收藏内容以及使用社区论坛的情况，您可自行上传头像、分享照片、音频和视频信息，您使用上传图片、发布音视频功能时，我们会根据您手机的系统版本分别请求您授权相机、相册、麦克风权限。您如果拒绝提供此类授权，将无法使用此相应服务，但不影响您正常使用奕境汽车APP/小程序的其他业务功能。若您已开启位置权限，您发布信息时可定位位置动态，展示同城动态及活动；如果您拒绝我们使用您的位置信息，您将在发布信息时无法选择位置定位，但您可以手动输入位置信息或不发布位置动态。您可以通过我们的服务与您的好友、家人及其他用户分享您的相关信息，包括在奕境汽车APP社区中公开分享文字和照片。请注意，您分享的内容中可能包含您的个人信息，请您审慎考虑披露您的个人信息。 <br data-v-19bb5c0c> 您在使用我们的产品和/或服务时，可能会提供或发布与您或其他用户相关的信息（包括您或其他用户发布的视频、文章、动态、评论或图片)，请您审慎考虑通过奕境汽车APP/小程序社区发布和传播的内容中含有您或其他用户的个人信息。在您向我们提供或发布其他用户的信息时，请确保您已取得合法授权。另外，如果您认为其他用户侵犯了您的合法权益，您可以通过本隐私政策提供的方式及时与我们联系。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 9.车主服务功能 <br data-v-19bb5c0c> 在您安装家用充电桩时，您需要提供您的姓名、手机号码、充电桩收货及勘测安装地址，以便我们向您邮寄、勘测、安装及维修家用充电桩。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 在您预约和进行车辆维修保养时，我们的客服服务和售后功能会使用您的账号信息或要求您提供其他信息用于核验身份，会收集您及送修人信息，包含姓名、手机号码、送修人有效证件号码信息（根据各地规定进行收集，部分城市要求机动车送修人进行实名登记）、联系地址、位置信息（用于推荐附近门店，我们将根据您的单独授权使用位置信息，您也可以选择手动输入），以及维修信息，包含车牌号、车辆VIN码、送修日期、送修里程、结算日期、故障描述、结算清单编号、燃料类型，并可能通过远程查看您的车辆故障。我们获取用户信息与用户车辆信息的目的是分析和解决故障问题，为用户维修车辆，准确保存车辆的维修保养记录，在维修保养过程中可以及时联系到用户，以及与用户进行沟通。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 当您使用取送车服务时，您需要提供您的车牌号、姓名、手机号码、取送车地址、取送车时间，以便我们为您提供取送车服务。您下单后可以选择第三方支付机构（包括微信、支付宝，具体以界面展示的支付方式为准）所提供的支付服务，我们需要将您的订单号与交易金额信息与这些支付机构共享，以实现其确认您的支付指令并完成支付。同时，我们依据前述信息给您开具相应发票。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 当您进行车辆充电时，我们会收集您的车辆VIN码、电池使用状况、充电桩及充电速率、充电状态、故障信息、充电记录相关信息，以便我们为您完成车辆充电服务。当您使用东风奕派APP公用充电产品或服务时，我们会收集您使用公用充电桩所需要的个人信息，具体以充电服务申请页面征得您同意的信息为准。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 当您使用车辆日志上传和共享图片时，为确保车辆日志上传、共享图片功能在后台稳定运行，APP会使用系统任务调度机制（workmanager中的android任务管理组件：androidx.work.impl.background.systemalarm.RescheduleReceiver）处理图片和日志上传任务。当用户切换应用后，相关任务可能会在后台继续执行，从而触发自启动或关联启动。所有上传内容均需用户明确同意，仅用于向用户的云服务存储同步，其他应用无法访问。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 10.商城购物功能 <br data-v-19bb5c0c> 当您在商城选购完商品准备对购物车内的商品进行结算时，系统会生成您购买该商品的订单。您需要在订单中填写收货人姓名、收货地址以及手机号码，同时该订单中会载明订单号、您所购买的商品或服务信息、您应支付的货款金额及支付方式。 <br data-v-19bb5c0c> 上述所有信息构成您的“订单信息”，当您下单后需使用线上支付功能时，您可以选择第三方支付机构（包括微信、支付宝等，具体以界面展示的支付方式为准）所提供的支付服务，我们需要将您的订单信息与您选择的第三方支付机构共享，以实现其确认您的支付指令并完成支付。同时，我们将依据前述信息给您开具相应发票。 <br data-v-19bb5c0c> 为履行我们与您的订单所必需，我们将使用您的订单信息与您进行身份核验、确定交易、支付结算、完成配送、为您查询订单以及提供客服咨询与售后服务（包括退换货服务）；我们还会使用您的订单信息来判断您的交易是否存在异常以保护您的交易安全。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 11.活动参与 <br data-v-19bb5c0c> 当您报名参加我们或与我们合作的第三方网络平台举办的线上/线下活动时，根据不同的活动性质，可能需要您提供不同的个人信息，且我们可能会将相关信息共享给提供相应服务的第三方（在征得您同意的情况下），具体以活动详情页和填报的信息为准。 <br data-v-19bb5c0c> 12.信息推送及推广 <br data-v-19bb5c0c> 奕境汽车APP/小程序可能会向您推送产品和/或服务的相关信息（包括商城订单提醒、社区消息提醒、服务提醒、活动提醒等），您可以在App“我的-设置-消息设置”选择关闭或开启。我们将不时向您发送我们认为您感兴趣的信息，包括我们的广告、促销及推广。但请您放心，如您不愿接收这些信息，可以通过手机短信中提供的退订方式进行退订，也可以联系奕境汽车APP进行退订或关闭。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 13.数据分析 <br data-v-19bb5c0c> 我们可能会对您使用我们产品和/或服务的日志信息、订单信息、试驾信息、购车信息、活动信息进行研究、加工、训练、统计、分析，以改善和优化我们的产品和服务。以上用于数据分析的信息不会标识出您的身份信息且我们仅保留分析结果。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 14.个性化内容推荐 <br data-v-19bb5c0c> 为了在奕境汽车小程序社区向您展示个性化内容，我们可能收集您使用我们的产品或服务的信息向您推荐您感兴趣的内容，我们提供的个性化内容推荐仅针对社区论坛内的内容推荐，您可通过“我的-设置-隐私设置”选择开启或关闭个性化内容推荐服务。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 15.收集和使用信息的其他规则 <br data-v-19bb5c0c> 根据相关法律法规，我们在以下情形中处理您的个人信息时无需征得您的授权同意： <br data-v-19bb5c0c> （1）为我们履行法律法规规定的责任或义务所必需，例如与国家安全、国防安全、公共安全以及与刑事侦查、起诉、审判和判决执行等直接相关的法定职责或者法定义务； <br data-v-19bb5c0c> （2）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需； <br data-v-19bb5c0c> （3）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息； <br data-v-19bb5c0c> （4）在合理的范围内处理您自行公开的个人信息，或者其他已经合法公开的个人信息（如合法的新闻报道、政府信息公开等渠道合法公开的个人信息） <br data-v-19bb5c0c> （5）出于维护产品/服务的安全稳定运行所必需，例如发现、识别、处理产品/服务运行故障； <br data-v-19bb5c0c> （6）法律法规规定的其他情形。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>二、信息的第三方合作、共享、转移和公开</h4><br data-v-19bb5c0c> 1、第三方合作 <br data-v-19bb5c0c> 为保障我们的产品/服务安全稳定地运行或实现相关功能，我们可能会接入由第三方提供的软件开发包（SDK），当您在我们的产品/服务中使用第三方SDK所提供的功能时，第三方SDK可能会收集处理您的个人信息。我们会对第三方获取信息的软件工具开发包（SDK）、应用程序接口（API）进行严格的安全监测，并约定严格的数据保护措施，令其按照本政策以及其他任何相关的保密和安全措施在征求您的同意下处理个人信息。为了最大程度保障您的信息安全，我们强烈建议您在使用任何第三方SDK类服务前先行查看其隐私条款；如果您发现这些SDK存在风险时，建议您立即终止相关操作并及时与我们取得联系。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 我们可能委托授权合作伙伴处理您的个人信息，以便授权合作伙伴代表我们为您提供某些服务或履行职能。我们将遵照法律法规的规定，对个人信息的对外提供进行严格的限制和管理。我们仅会出于本政策的合法、正当、必要、特定、明确的目的委托其处理您的信息，授权合作伙伴只能接触到其履行职责所需信息，且我们将会通过协议要求其不得将此信息用于其他任何超出委托范围的目的。如果授权合作伙伴将您的信息用于我们未委托的用途，其将单独征得您的同意。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 我们与第三方合作过程中，将遵守合法原则、正当与最小必要原则、安全审慎原则，审慎评估第三方使用数据的目的，对第三方的安全保障能力进行综合评估，并要求其遵循合作协议。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 2、共享 <br data-v-19bb5c0c> 当您在我们的产品中使用由第三方提供的功能时，我们会将实现业务功能所必需的信息与这些第三方共享。共享时，我们会单独获取您的授权，我们不会向东风奕派小程序以外的任何第三方共享您的个人信息，但以下情形除外： <br data-v-19bb5c0c> （1）法定情形下的共享： <br data-v-19bb5c0c> 我们可能会根据法律法规规定、诉讼、争议解决需要，或按照行政、司法机关依法提出的要求，共享、披露您的个人信息。 <br data-v-19bb5c0c> （2）与关联公司之间共享： <br data-v-19bb5c0c> 为便于我们与关联公司共同向您提供部分服务，我们会在遵循统一管理和控制的关联公司之间共享您的信息，且受本隐私政策中所声明目的的约束。如果我们的关联公司改变个人信息处理目的，将再次征求您的授权同意。 <br data-v-19bb5c0c> （3）为实现我们的服务/功能所必须进行的共享 <br data-v-19bb5c0c> 当您在我们的产品中使用由第三方提供的功能时，我们会将实现业务功能所必需的信息与这些第三方共享。 <br data-v-19bb5c0c> （4）与我们的部分合作伙伴的必要共享 <br data-v-19bb5c0c> 我们可能委托授权合作伙伴处理您的个人信息，以便授权合作伙伴代表我们为您提供某些服务或履行职能。我们仅会出于本政策的合法、正当、必要、特定、明确的目的委托其处理您的信息，授权合作伙伴只能接触到其履行职责所需信息，且我们将会通过协议要求其不得将此信息用于其他任何超出委托范围的目的。如果授权合作伙伴将您的信息用于我们未委托的用途，其将单独征得您的同意。 <br data-v-19bb5c0c> 3、转移 <br data-v-19bb5c0c> 原则上我们不会将您的个人信息向其他公司、组织或个人进行转移。但随着我们业务的持续发展，我们将有可能进行合并、分立、解散等需转移您的个人信息，在发生前述变更时，我们会向您告知接收方的名称或者姓名和联系方式，并要求新的持有您个人信息的公司、组织继续受本隐私政策的约束，否则，我们将要求该公司、组织重新向您征求授权同意。 <br data-v-19bb5c0c> 4、公开 <br data-v-19bb5c0c> 除非获取您的单独同意或您主动披露的信息外，我们不会公开披露您的个人信息。 <br data-v-19bb5c0c> 特别提示：使用我们的产品和/或服务过程中，您主动公开分享、共享的个人信息，不受本隐私政策限制（如向其他互联网平台转发内容）。您应注意，任何您分享的信息均可被任何第三方阅读、收集和使用，请您审慎考虑您通过奕境汽车APP/小程序发布和传播的内容以及其中可能指向您个人的信息。您充分了解，当您自行作出披露时，只要您不删除您公开发布的信息，该信息可能会一直留存在公众领域；在一些情况下，即使您删除您公开发布的信息，该等信息仍可由其他用户或与奕境汽车APP/小程序没有关联及不受奕境汽车APP/小程序控制的第三方独立地缓存、复制或储存，或通过其他用户或第三方在公众领域保存。例如，当您将您在我们的产品和/或服务发表的回答转发到其他互联网平台，该平台将独立地展示、缓存或保存您转发的内容，可能其他互联网用户也会转发、保存您的回答，而相应的页面将不受我们的控制。 <br data-v-19bb5c0c> 5.信息的共享、转移、公开时征得授权同意的例外 <br data-v-19bb5c0c> 以下情形中，共享、转移、公开您的个人信息时无需征得您的授权同意： <br data-v-19bb5c0c> (1)为我们履行法律法规规定的责任或义务所必需，例如与国家安全、国防安全、公共安全以及与刑事侦查、起诉、审判和判决执行等直接相关的法定职责或者法定义务； <br data-v-19bb5c0c> (2)为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需； <br data-v-19bb5c0c> (3)为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息； <br data-v-19bb5c0c> (4)在合理的范围内处理您自行公开的个人信息，或者其他已经合法公开的个人信息（如合法的新闻报道、政府信息公开等渠道合法公开的个人信息） <br data-v-19bb5c0c> (5)出于维护产品/服务的安全稳定运行所必需，例如发现、识别、处理产品/服务运行故障； <br data-v-19bb5c0c> (6)法律法规规定的其他情形。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 6.使用第三方SDK收集用户信息及用途 <br data-v-19bb5c0c> 详细下列见《奕境汽车APP/小程序第三方SDK列表》 <br data-v-19bb5c0c><br data-v-19bb5c0c> (1)方舟智能分析SDK（小程序版） <br data-v-19bb5c0c> 第三方公司：深圳易观数字科技有限公司（原北京易观智库网络科技有限公司）服务平台：奕境汽车小程序 <br data-v-19bb5c0c> 收集数据类型：设备基础信息、设备匿名标识、网络信息、访问页面、操作行为、应用运行日志、匿名化统计数据。 <br data-v-19bb5c0c> 收集目的：用于小程序用户行为统计、数据分析、运行异常监测，优化产品功能与使用体验，提升服务稳定性。 <br data-v-19bb5c0c> 收集目的：遵照国家监管规定，为了保证您在使用本客户端办理业务、参与活动时的合法性和安全性，防范网络安全风险、防止移动应用软件被恶意篡改、防止您个人的损失和不良影响，我们使用了北京梆梆安全科技有限公司的APP加固技术，已达到防止针对移动应用的反编译、二次打包、内存注入、动态调试、数据窃取、交易劫持、应用钓鱼等恶意攻击行为，保护应用软件安全。 <br data-v-19bb5c0c> 采集方式：以匿名化、去标识化方式采集数据，仅用于统计分析，不收集敏感个人信息，不对外共享用户信息。 <br data-v-19bb5c0c> 隐私政策链接：https://docs.analysysdata.com/@uba-docs/yinsishengming.html <br data-v-19bb5c0c><br data-v-19bb5c0c> (2)微信号码认证服务 <br data-v-19bb5c0c> 第三方公司：深圳市腾讯计算机系统有限公司 <br data-v-19bb5c0c> 服务平台：奕境汽车小程序 <br data-v-19bb5c0c> 收集数据类型：网络环境信息、设备基础信息、运营商校验信息，经用户授权后获取本机手机号码。 <br data-v-19bb5c0c> 收集目的：实现小程序本机号码一键登录、手机号核验、身份安全校验，简化登录流程，保障账号使用安全。 <br data-v-19bb5c0c> 收集目的：用于保障用户账号登录和功能实现过程中的安全风控；用于实现微博分享功能，将用户选择的图片或视频分享至微博 <br data-v-19bb5c0c> 采集方式：仅在用户主动授权后获取相关信息，仅用于号码认证及登录校验场景，无额外采集，不储存、不泄露用户信息。 <br data-v-19bb5c0c> 隐私政策链接：https://developers.weixin.qq.com/miniprogram/dev/platform-capabilities/miniapp/pre-read/sdk/agreement/sdk.html <br data-v-19bb5c0c><br data-v-19bb5c0c> (3)微信小程序定位服务（位置信息） <br data-v-19bb5c0c> 第三方公司：深圳市腾讯计算机系统有限公司 <br data-v-19bb5c0c> 服务平台：奕境汽车小程序 <br data-v-19bb5c0c> 收集数据类型：设备信息、网络信息、经用户授权后获取模糊 / 精确地理位置（经纬度、所在城市）。 <br data-v-19bb5c0c> 收集目的：用于预约品鉴、留资表单中自动获取当前所在城市，快速填充 “选择城市”“用车城市” 字段，简化用户操作。 <br data-v-19bb5c0c> 采集方式：仅在用户点击授权后获取，仅用于城市选择与表单填充，不上传长期存储，不用于其他用途。 <br data-v-19bb5c0c> 隐私政策链接：https://privacy.qq.com/document/preview/dbd484ce652c486cb6d7e43ef12cefb0 <br data-v-19bb5c0c> (4)高德开放平台定位 SDK <br data-v-19bb5c0c> 第三方公司：高德软件有限公司 <br data-v-19bb5c0c> 服务平台：奕境官网 <br data-v-19bb5c0c> 收集数据类型：经用户授权后获取模糊 / 精确地理位置（经纬度、所在城市）。 <br data-v-19bb5c0c> 收集目的：用于预约品鉴、留资表单中自动获取当前所在城市。 <br data-v-19bb5c0c> 采集方式：仅在用户点击授权后获取，仅用于获取城市与表单填充，不上传长期存储，不用于其他用途。 <br data-v-19bb5c0c> 隐私政策链接：https://cache.amap.com/h5/h5/publish/238/index.html <br data-v-19bb5c0c><br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>三、信息的存储和保护</h4><br data-v-19bb5c0c> 我们非常重视您的个人信息安全，将采取符合业界标准、合理可行的安全防护措施保护您的个人信息，防止数据遭到未经授权的访问、披露、使用、修改、损坏、丢失或泄露。例如我们会使用加密技术，保障个人信息存储、传输的安全性；我们会使用受信赖的保护机制防止数据遭到恶意攻击。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 我们会从组织建设、制度和流程设计、人员管理、产品技术等多方面多维度提升个人信息的安全性。我们采取严格的数据使用和访问制度，仅允许有必要知晓信息的人员访问个人信息，并设置了访问权限控制和监控机制。我们会举办信息安全和隐私保护培训课程，加强员工对保护个人信息重要性的认识。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 尽管已经采取了上述合理有效措施，并已经遵守了相关法律法规要求的标准，但请您理解，由于技术的限制以及可能存在的各种恶意手段，在互联网行业，即便竭尽所能加强安全措施，但是任何安全措施都无法做到百分百安全。如果您有理由认为我们的服务存在信息安全风险，请及时告知我们，联系方式见本政策“联系我们”。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 在不幸发生个人信息安全事件后，我们将按照法律法规的要求，及时向您告知安全事件的基本情况和可能的影响、我们已采取或将要采取的处置措施、您可自主防范和降低风险的建议、对您的补救措施等。我们同时将及时将事件相关情况以邮件、信函、电话、推送通知等方式告知您，难以逐一告知个人信息主体时，我们会采取合理、有效的方式发布公告。同时，我们还将按照监管部门要求，主动上报个人信息安全事件的处置情况。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 互联网并非绝对安全的环境，而且电子邮件、即时通讯及与其他用户的交流方式并未加密，我们强烈建议您不要通过此类方式发送个人信息（尤其是个人敏感信息）。请使用复杂密码，协助我们保证您的账号安全。我们将尽最大努力保障您的个人信息安全，采用技术手段限制他人未经授权访问、使用或者披露您的个人信息。尽管采取上述措施，但请您理解，由于目前技术发展的限制以及可能存在的各种恶意手段，即便我们竭尽所能加强安全措施，也不可能始终完全保证个人信息百分之百的安全。您需要了解，您接入奕境三端平台、车载应用平台和汽车产品配套车机端设备所用的系统和通讯网络，有可能因我们可控范围外的因素而出现问题。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>四、存储期限和超期使用说明</h4><br data-v-19bb5c0c> 我们依照法律法规的规定，将在境内运营过程中收集和产生的您的个人信息存储在中国境内，位于由我们管控的武汉、十堰的数据中心。我们不会将您的个人信息传输至境外，如果我们向境外传输，我们将会严格遵循相关法律法规政策要求或单独征求您的授权同意。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 我们仅在为实现本隐私政策所述目的所必需的期限内留存您的个人信息，法律法规另有规定或者个人信息主体另行授权同意的除外。根据您使用的产品/服务不同，您的个人信息存储期限可能会有所差别。我们判断个人信息的存储期限主要依据以下标准： <br data-v-19bb5c0c> 1)完成与您相关的产品与服务目的、维护相应产品及业务记录，以应对您可能的查询或投诉； <br data-v-19bb5c0c> 2)保证我们为您提供服务的安全和质量； <br data-v-19bb5c0c> 3)您是否同意更长的留存期间； <br data-v-19bb5c0c> 4)根据诉讼时效的相关要求； <br data-v-19bb5c0c> 5)是否存在关于存储期限的其他特别约定或法律法规规定。(例如:根据《中华人民共和国电子商务法》，电子商务平台经营者应兰确保其商品和服务信息、交易信息保存时间自交易完成之日起不少于三年:根据《中华人民共和国网络安全法》，网络运营者应当采取监测、记录网络运行状态、网络安全事件的技术措施，并按照规定留存相关的网络日志不少于六个月)。 <br data-v-19bb5c0c> 超出存储期限后，我们会对您的个人信息进行删除或匿名化处理。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>五、您的权利</h4><br data-v-19bb5c0c> 我们非常重视您对个人信息的关注，并尽全力保护您对您个人信息查阅、复制、更正、补充、删除以及撤回同意等权利，以使您拥有充分的能力保障您的隐私和安全。按照中国相关的法律、法规、标准，我们保障您对自己的个人信息行使以下权利： <br data-v-19bb5c0c><br data-v-19bb5c0c> 1.查阅您的个人账号信息 <br data-v-19bb5c0c> 您有权以下列方式随时查阅奕境汽车APP/小程序中存储的您的个人账号信息，具体操作方式为：点击奕境汽车APP/小程序中的“我的-设置-个人中心-个人资料、账号安全”。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 2.更正、补充您的个人信息 <br data-v-19bb5c0c> 当您发现我们处理的关于您的个人信息有错误时，您有权要求我们做出更正、补充，具体操作方式为：点击奕境汽车APP/小程序中的“我的-设置-个人中心-个人资料”。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 3.删除您的个人信息 <br data-v-19bb5c0c> 您可以发送电子邮件向我们提出删除个人信息的请求，但已进行个人信息匿名化处理或法律法规另有规定的除外，删除时需对您进行身份核验且请您明确需删除的具体个人信息类型，我们将根据国家法律法规及监管的要求响应您的请求。 <br data-v-19bb5c0c> 您或我们协助您删除相关信息后，因为适用的法律和安全技术限制，我们可能无法立即从备份系统中删除相应的信息，我们将安全地存储您的个人信息并限制对其进一步的处理，直到备份可以清除或实现匿名化。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 4.改变您授权同意的范围或撤回您的授权 <br data-v-19bb5c0c> 您可以在奕境APP/小程序“我的-设置-权限管理”关闭位置、相册、相机、麦克风、蓝牙、电话等权限改变同意范围或撤回您的授权。 <br data-v-19bb5c0c> 请您理解，每个业务功能需要一些基本的个人信息才能得以完成（见本隐私政策“一、我们如何收集和使用您的个人信息”），当您撤回同意或授权后，我们将无法继续为您提供撤回同意或授权所对应的服务，也不再处理您相应的个人信息。但您撤回同意或授权的决定，不会影响此前基于您的授权而开展的个人信息处理。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 5.注销账号 <br data-v-19bb5c0c> 您可以在奕境汽车APP/小程序“我的-设置-注销账号”里申请注销账号。当您满足我们公示的注销账号申请条件且成功申请注销奕境汽车APP/小程序账号后，我们将停止为您提供我们的产品和/或服务，除法律法规另有规定外，我们将删除您的个人信息或对您个人信息做匿名化处理。 <br data-v-19bb5c0c><br data-v-19bb5c0c> 6.响应您的请求 <br data-v-19bb5c0c> 为保障您的账户安全和您的个人信息安全，您向我们提出上述权利请求时，我们可能需要您证明自己的身份并提供书面申请或其他合理方式后再处理您的请求。我们一般会在收到申请并验证您身份后的10个工作日内响应您的请求；如果您的请求较为复杂，或实现您的权利请求需要较大工作量，我们可能会适当延长响应期限。 <br data-v-19bb5c0c> 请您知悉，我们在不同的版本或操作系统中提供的管理方式的路径可能有差异，请以实际为准。为了优化您的使用体验，我们也可能对操作设置进行调整。如您对行使相关权利的方式及途径仍有任何疑问的，对于无法通过产品/服务界面自行操作的权利，您可以与我们联系。 <br data-v-19bb5c0c> 请您理解，对于与您的自然人身份不直接关联或不具备可识性的信息，以及对于无合理理由重复申请的信息，或者需要过多技术手段（例如，需要开发新系统或从根本上改变现行惯例）或者不切实际的请求，我们可以予以拒绝。 <br data-v-19bb5c0c> 在以下情形中，我们将无法响应您的请求 <br data-v-19bb5c0c> (1)为我们履行法律法规规定的责任或义务所必需，例如与国家安全、国防安全、公共安全以及与刑事侦查、起诉、审判和判决执行等直接相关的法定职责或者法定义务； <br data-v-19bb5c0c> (2)为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需； <br data-v-19bb5c0c> (3)为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息； <br data-v-19bb5c0c> (4)在合理的范围内处理您自行公开的个人信息，或者其他已经合法公开的个人信息（如合法的新闻报道、政府信息公开等渠道合法公开的个人信息）； <br data-v-19bb5c0c> (5)有充分证据证明您存在主观恶意或滥用权利的； <br data-v-19bb5c0c> (6)响应您的请求将导致您或其他个人、组织的合法权益受到的； <br data-v-19bb5c0c> (7)可能涉及商业秘密的； <br data-v-19bb5c0c> (8)关于与您自然人身份不直接关联或具备可识别性的信息的请求； <br data-v-19bb5c0c> (9)法律法规规定的其他情形。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>六、未成年人信息</h4><br data-v-19bb5c0c> 我们的产品/服务主要适用于成年人，我们不会在明知的情况下主动收集未成年人个人信息。 <br data-v-19bb5c0c> 对于不满十四周岁的儿童，我们仅在取得其监护人明示同意的情况下，且为实现特定功能所必需时，才收集其个人信息。我们已制定专门的《儿童个人信息保护规则》（可通过[链接]查阅），并将严格遵循最小必要原则，采取更严格的保护措施。若监护人发现我们在未获同意的情况下收集了儿童信息，请通过本政策公布的联系方式通知我们，我们将尽快删除。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>七、政策更新</h4><br data-v-19bb5c0c> 为给您提供更好地服务以及随着我们业务的发展，本隐私政策也会随之更新。但未经您明确同意，我们不会削减您依据过往隐私政策所应享有的权利。我们会发出更新版本并在生效前通过公告或以其他适当方式提醒您相关内容的更新，也请您及时登录奕境三端平台以了解最新的隐私政策。我们还会将隐私政策的旧版本存档，供您查阅。 <br data-v-19bb5c0c> 对于重大变更，我们还会提供更为显著的通知（我们会通过包括但不限于邮件、短信或在浏览页面做特别提示等方式，说明隐私政策的具体变更内容）。本隐私政策所指的重大变更包括但不限于： <br data-v-19bb5c0c> 我们的产品和/或服务模式发生重大变化，如处理个人信息的目的、处理的个人信息类型、个人信息的使用方式等； <br data-v-19bb5c0c> 我们在所有权结构、组织架构等方面发生重大变化，如业务调整、破产并购等引起的所有者变更等； <br data-v-19bb5c0c> 个人信息共享、转让或公开披露的主要对象发生变化； <br data-v-19bb5c0c> 您参与个人信息处理方面的权利及其行使方式发生重大变化； <br data-v-19bb5c0c> 我们负责处理个人信息安全的责任部门、联络方式及投诉渠道发生变化时； <br data-v-19bb5c0c> 个人信息安全影响评估报告表明存在高风险时。 <br data-v-19bb5c0c><br data-v-19bb5c0c><h4 data-v-19bb5c0c>八、联系我们</h4><br data-v-19bb5c0c> 如果您希望行使您在本隐私政策下享有的权利，您对本隐私政策有任何意见或问题，或者您对我们收集、使用或披露您的个人信息有任何问题，您可以通过如下方式联系我们：privacy-yijing@dfpv.com.cn，收到您的请求后，我们将在10个工作日内做出回复，感谢您的耐心与理解。考虑到要求的复杂性和数量，在必要的时候，这一期限可能另外延长15个工作日。 ",376))]),v(l,{name:"fade"},{default:s(()=>[m.value?(a(),c("div",{key:0,class:"image-preview-overlay",onClick:n[3]||(n[3]=b=>m.value=!1)},[t("div",{class:"close-btn",onClick:n[1]||(n[1]=e(b=>m.value=!1,["stop"]))},"×"),t("div",y,[t("img",{src:r(p),class:"expanded-image",onClick:n[2]||(n[2]=e(()=>{},["stop"]))},null,8,k)])])):i("",!0)]),_:1})]))}},[["__scopeId","data-v-19bb5c0c"]]),w={class:"wrap law-news"},x=b({__name:"index",setup(b){u(m.law);const d=o(2);return(b,r)=>(a(),c(p,null,[v(h),t("section",w,[r[0]||(r[0]=t("div",{class:"law-head"},[t("h2",null,"奕境汽车隐私政策"),t("p",null,"生效日期：2026 年 4 月 20 日")],-1)),2==d.value?(a(),P(f,{key:0})):i("",!0)])],64))}},[["__scopeId","data-v-53acea39"]]);export{x as default};
